// Experiment 2A uniform-FP32 timing harness.  Validation/measurement-only:
// it invokes existing public APIs and does not implement a numerical method.
#include "bspai/fp32_cuda_spai.hpp"
#include "bspai/fp32_cuda_gmres.hpp"
#include <cuda_runtime_api.h>
#include <chrono>
#include <cmath>
#include <fstream>
#include <iomanip>
#include <iostream>
#include <limits>
#include <sstream>
#include <stdexcept>
#include <string>
#include <vector>

#define cuda_spai_wall_clock cuda_spai_telemetry

namespace {
using Clock = std::chrono::steady_clock;
struct Args { std::string matrix, mode, rhs="periodic7", p_path, p_output; float epsilon=.3f; std::size_t alpha=0,beta=8,innercap=0,outercap=20,warmups=3,trials=3; };
std::size_t count(const std::string& s) { std::size_t used=0; const unsigned long long v=std::stoull(s,&used); if (used!=s.size()) throw std::invalid_argument("invalid count"); return static_cast<std::size_t>(v); }
std::string quote(const std::string& s) { std::string r="\""; for(char c:s) { if(c=='\\' || c=='\"') r+='\\'; r+=c; } return r+'\"'; }
Args parse(int argc,char** argv) { Args a; for(int i=1;i<argc;i+=2) { if(i+1==argc || std::string(argv[i]).compare(0,2,"--")) throw std::invalid_argument("arguments are --key value pairs"); std::string k(argv[i]),v(argv[i+1]); if(k=="--matrix")a.matrix=v; else if(k=="--mode")a.mode=v; else if(k=="--rhs")a.rhs=v; else if(k=="--p")a.p_path=v; else if(k=="--p-output")a.p_output=v; else if(k=="--epsilon")a.epsilon=std::stof(v); else if(k=="--alpha")a.alpha=count(v); else if(k=="--beta")a.beta=count(v); else if(k=="--innercap")a.innercap=count(v); else if(k=="--outercap")a.outercap=count(v); else if(k=="--warmups")a.warmups=count(v); else if(k=="--trials")a.trials=count(v); else throw std::invalid_argument("unknown option: "+k); } if(a.matrix.empty()||a.mode.empty()||!std::isfinite(a.epsilon)||a.epsilon<=0||!a.alpha||!a.beta||!a.innercap||a.outercap>20) throw std::invalid_argument("invalid frozen options"); return a; }
bspai::Fp32CsrMatrix load(const std::string& path) { std::ifstream in(path.c_str()); if(!in) throw std::invalid_argument("cannot open matrix"); std::string line; if(!std::getline(in,line)||line!="%%MatrixMarket matrix coordinate real general") throw std::invalid_argument("expected general real Matrix Market"); do { if(!std::getline(in,line)) throw std::invalid_argument("missing dimensions"); } while(!line.empty()&&line[0]=='%'); std::istringstream dim(line); std::size_t n=0,m=0,nnz=0; if(!(dim>>n>>m>>nnz)||!n||n!=m) throw std::invalid_argument("expected nonempty square matrix"); std::vector<bspai::Fp32Entry> e; e.reserve(nnz); for(std::size_t k=0;k<nnz;++k) { if(!std::getline(in,line)) throw std::invalid_argument("truncated matrix"); std::istringstream row(line); std::size_t i=0,j=0; std::string text; if(!(row>>i>>j>>text)||!i||!j||i>n||j>m) throw std::invalid_argument("bad entry"); std::size_t used=0; float v=std::stof(text,&used); if(used!=text.size()||!std::isfinite(v)) throw std::invalid_argument("bad FP32 entry"); e.push_back({i-1,j-1,v}); } return bspai::Fp32CsrMatrix::from_entries(n,m,e); }
void write_mm(const std::string& path,const bspai::Fp32CsrMatrix& a) { std::ofstream out(path.c_str(),std::ios::trunc); if(!out) throw std::runtime_error("cannot create fixed P"); out<<std::setprecision(std::numeric_limits<float>::max_digits10)<<"%%MatrixMarket matrix coordinate real general\n% Experiment2A canonical FP32 CPU P; prepared outside timing\n"<<a.rows()<<' '<<a.cols()<<' '<<a.values().size()<<'\n'; for(std::size_t i=0;i<a.rows();++i) for(std::size_t k=a.row_offsets()[i];k<a.row_offsets()[i+1];++k) out<<i+1<<' '<<a.column_indices()[k]+1<<' '<<a.values()[k]<<'\n'; if(!out) throw std::runtime_error("fixed P write failure"); }
std::vector<float> truth(std::size_t n,const std::string& kind) { if(kind!="periodic7") throw std::invalid_argument("only periodic7 RHS is frozen for Experiment 2A"); std::vector<float> x(n); for(std::size_t i=0;i<n;++i)x[i]=static_cast<float>(static_cast<int>(i%7)-3)/4.0f; return x; }
bspai::Fp32IrOptions options(const Args& a,std::size_t n) { if(a.alpha!=(n+7)/8||a.innercap!=n) throw std::invalid_argument("Experiment 2A requires alpha=ceil(n/8), cap=n"); bspai::Fp32IrOptions o; o.spai.epsilon=a.epsilon;o.spai.alpha=a.alpha;o.spai.beta=a.beta;o.gmres.tolerance=1e-4f;o.gmres.max_iterations=a.innercap;o.max_outer_steps=a.outercap; return o; }
void sync() { cudaError_t e=cudaDeviceSynchronize(); if(e!=cudaSuccess) throw std::runtime_error(cudaGetErrorString(e)); }
void values(std::ostream& out,const std::vector<float>& x) { out<<'['; for(std::size_t i=0;i<x.size();++i) { if(i)out<<','; out<<x[i]; } out<<']'; }
void construction(std::ostream& o,const bspai::Fp32SpaiResult& r) { std::size_t fits=0,growths=0; for(const auto& c:r.columns){fits+=c.fits;growths+=c.growths;} o<<"\"construction_status\":"<<quote(bspai::fp32_spai_status_name(r.status))<<",\"construction_nnz_p\":"<<r.preconditioner_nnz<<",\"construction_fit_count\":"<<fits<<",\"construction_growth_count\":"<<growths; }
void diag(std::ostream& o,const bspai::Fp32CsrMatrix& a,const std::vector<float>& b,const std::vector<float>& x) { const auto d=bspai::fp32_evaluate_ir_diagnostics(a,b,x); o<<"\"original_residual_2\":"<<d.residual_2<<",\"original_residual_inf\":"<<d.residual_inf<<",\"normwise_backward_error\":"<<d.normwise_backward_error<<",\"backward_tolerance\":"<<bspai::fp32_ir_backward_tolerance(); }
void work(std::ostream& o,const bspai::Fp32IrResult& r) { std::size_t total=0,accepted=0; for(const auto& g:r.inner_history){total+=g.iterations;if(g.converged)++accepted;} o<<"\"inner_iterations_total\":"<<total<<",\"inner_accepted_count\":"<<accepted; }
void cuda_spai_telemetry(std::ostream& o,const bspai::Fp32CudaSpaiTelemetry& t) { o<<",\"gpu_spai_telemetry\":{\"allocation_calls\":"<<t.device_allocation_calls<<",\"free_calls\":"<<t.device_free_calls<<",\"reallocation_calls\":"<<t.device_reallocation_calls<<",\"allocated_bytes_cumulative\":"<<t.device_allocated_bytes<<",\"freed_bytes_cumulative\":"<<t.device_freed_bytes<<",\"peak_device_bytes\":"<<t.peak_device_bytes<<",\"max_single_allocation_bytes\":"<<t.max_single_allocation_bytes<<",\"current_device_bytes_at_return\":"<<t.current_device_bytes<<",\"outstanding_allocations_at_return\":"<<t.outstanding_device_allocations<<",\"allocation_wall_ms\":"<<t.allocation_wall_ms<<",\"free_wall_ms\":"<<t.free_wall_ms<<",\"uploads\":"<<t.uploads<<",\"upload_bytes\":"<<t.upload_bytes<<",\"upload_min_bytes\":"<<t.upload_min_bytes<<",\"upload_max_bytes\":"<<t.upload_max_bytes<<",\"upload_size_buckets\":{\"le_256\":"<<t.upload_le_256_bytes<<",\"le_4096\":"<<t.upload_le_4096_bytes<<",\"gt_4096\":"<<t.upload_gt_4096_bytes<<"},\"downloads\":"<<t.downloads<<",\"download_bytes\":"<<t.download_bytes<<",\"download_min_bytes\":"<<t.download_min_bytes<<",\"download_max_bytes\":"<<t.download_max_bytes<<",\"download_size_buckets\":{\"le_256\":"<<t.download_le_256_bytes<<",\"le_4096\":"<<t.download_le_4096_bytes<<",\"gt_4096\":"<<t.download_gt_4096_bytes<<"},\"synchronizations\":{\"upload_lifetime\":"<<t.upload_synchronizations<<",\"download_lifetime\":"<<t.download_synchronizations<<",\"explicit_completion\":"<<t.explicit_synchronizations<<"},\"streams\":"<<t.streams_created<<",\"qr_submissions\":"<<t.qr_submissions<<",\"score_evaluations\":"<<t.gpu_score_evaluations<<",\"wall_clock_ms\":{\"total\":"<<t.construction_wall_total_ms<<",\"matrix_setup\":"<<t.construction_wall_matrix_setup_ms<<",\"adaptive_fits\":"<<t.construction_wall_adaptive_fits_ms<<",\"packing_assembly\":"<<t.construction_wall_packing_assembly_ms<<"}}"; }
template<class Run,class Post> void samples(const Args&a,bool gpu,Run run,Post post) { for(std::size_t ordinal=0;ordinal<a.warmups+a.trials;++ordinal) { const bool measured=ordinal>=a.warmups; if(gpu)sync(); const auto begin=Clock::now(); try { const auto r=run(); if(gpu)sync(); const double ms=std::chrono::duration<double,std::milli>(Clock::now()-begin).count(); std::ostringstream body; body<<std::setprecision(std::numeric_limits<float>::max_digits10); post(body,r); std::cout<<std::setprecision(std::numeric_limits<double>::max_digits10)<<"{\"schema_version\":1,\"event\":\"sample\",\"precision\":\"fp32\",\"mode\":"<<quote(a.mode)<<",\"phase\":"<<quote(measured?"measured":"warmup")<<",\"ordinal\":"<<ordinal<<",\"elapsed_ms\":"<<ms<<",\"timing_components\":{\"primary_public_api_and_sync_ms\":"<<ms<<",\"separate_setup_transfer_cleanup_ms\":null},"<<body.str()<<"}\n"; } catch(const std::exception&e) { if(gpu){try{sync();}catch(...){}} const double ms=std::chrono::duration<double,std::milli>(Clock::now()-begin).count(); std::cout<<"{\"schema_version\":1,\"event\":\"sample\",\"precision\":\"fp32\",\"mode\":"<<quote(a.mode)<<",\"phase\":"<<quote(measured?"measured":"warmup")<<",\"ordinal\":"<<ordinal<<",\"elapsed_ms\":"<<ms<<",\"status\":\"harness_exception\",\"converged\":false,\"harness_exception\":"<<quote(e.what())<<"}\n"; } } }
}
int main(int argc,char** argv) { try { const Args a=parse(argc,argv); const auto A=load(a.matrix); const auto o=options(a,A.rows()); const auto x=truth(A.rows(),a.rhs); const auto b=A.multiply(x); if(a.mode=="gpu_ir_fixed") {
    if(a.p_path.empty()) throw std::invalid_argument("missing --p");
    const auto P=load(a.p_path);
    samples(a,true,[&](){return bspai::fp32_cuda_refine_with_preconditioner(A,P,b,o);},
      [&](std::ostream&z,const bspai::Fp32IrResult&r){
        z<<"\"status\":"<<quote(bspai::fp32_ir_status_name(r.status))
         <<",\"converged\":"<<(r.converged?"true":"false")
         <<",\"outer_steps\":"<<r.outer_steps
         <<",\"inner_attempts\":"<<r.inner_attempts<<',';
        work(z,r);z<<',';diag(z,A,b,r.solution);
        z<<",\"solution\":";values(z,r.solution);
      });
    return 0;
} if(a.mode=="prepare_fixed_p") { if(a.p_output.empty())throw std::invalid_argument("missing --p-output"); const auto r=bspai::fp32_construct_spai(A,o.spai); if(r.status==bspai::Fp32SpaiStatus::success)write_mm(a.p_output,r.preconditioner); std::cout<<"{\"schema_version\":1,\"event\":\"fixed_p_preparation\",\"precision\":\"fp32\",";construction(std::cout,r);std::cout<<",\"p_output\":"<<quote(a.p_output)<<"}\n";return r.status==bspai::Fp32SpaiStatus::success?0:1;} if(a.mode=="cpu_spai")samples(a,false,[&](){return bspai::fp32_construct_spai(A,o.spai);},[&](std::ostream&z,const bspai::Fp32SpaiResult&r){construction(z,r);z<<",\"status\":"<<quote(bspai::fp32_spai_status_name(r.status))<<",\"converged\":"<<(r.status==bspai::Fp32SpaiStatus::success?"true":"false");}); else if(a.mode=="gpu_spai")samples(a,true,[&](){return bspai::fp32_cuda_construct_spai(A,o.spai);},[&](std::ostream&z,const bspai::Fp32CudaSpaiResult&r){construction(z,r.construction);z<<",\"status\":"<<quote(bspai::fp32_spai_status_name(r.construction.status))<<",\"converged\":"<<(r.construction.status==bspai::Fp32SpaiStatus::success?"true":"false");cuda_spai_wall_clock(z,r.telemetry);}); else if(a.mode=="cpu_pipeline")samples(a,false,[&](){return bspai::fp32_spai_gmres_ir(A,b,o);},[&](std::ostream&z,const bspai::Fp32IrResult&r){z<<"\"status\":"<<quote(bspai::fp32_ir_status_name(r.status))<<",\"converged\":"<<(r.converged?"true":"false")<<",\"outer_steps\":"<<r.outer_steps<<",\"inner_attempts\":"<<r.inner_attempts<<',';construction(z,r.construction);z<<',';work(z,r);z<<',';diag(z,A,b,r.solution);z<<",\"solution\":";values(z,r.solution);}); else if(a.mode=="gpu_pipeline")samples(a,true,[&](){return bspai::fp32_cuda_spai_gmres_ir(A,b,o);},[&](std::ostream&z,const bspai::Fp32IrResult&r){z<<"\"status\":"<<quote(bspai::fp32_ir_status_name(r.status))<<",\"converged\":"<<(r.converged?"true":"false")<<",\"outer_steps\":"<<r.outer_steps<<",\"inner_attempts\":"<<r.inner_attempts<<',';construction(z,r.construction);z<<',';work(z,r);z<<',';diag(z,A,b,r.solution);z<<",\"solution\":";values(z,r.solution);}); else if(a.mode=="cpu_gmres_fixed"||a.mode=="gpu_gmres_fixed") { if(a.p_path.empty())throw std::invalid_argument("missing --p");const auto P=load(a.p_path);if(a.mode=="cpu_gmres_fixed")samples(a,false,[&](){return bspai::fp32_left_preconditioned_gmres(A,P,b,o.gmres);},[&](std::ostream&z,const bspai::Fp32GmresResult&r){z<<"\"status\":"<<quote(bspai::fp32_gmres_status_name(r.status))<<",\"converged\":"<<(r.converged?"true":"false")<<",\"iterations\":"<<r.iterations<<",\"final_preconditioned_relative\":"<<r.final_preconditioned_relative<<',';diag(z,A,b,r.solution);z<<",\"solution\":";values(z,r.solution);});else samples(a,true,[&](){return bspai::fp32_cuda_left_preconditioned_gmres(A,P,b,o.gmres);},[&](std::ostream&z,const bspai::Fp32GmresResult&r){z<<"\"status\":"<<quote(bspai::fp32_gmres_status_name(r.status))<<",\"converged\":"<<(r.converged?"true":"false")<<",\"iterations\":"<<r.iterations<<",\"final_preconditioned_relative\":"<<r.final_preconditioned_relative<<',';diag(z,A,b,r.solution);z<<",\"solution\":";values(z,r.solution);}); } else throw std::invalid_argument("unknown mode"); return 0; } catch(const std::exception&e) { std::cerr<<"experiment2a_fp32_benchmark: "<<e.what()<<'\n';return 2; } }
